#[derive(Debug)]
enum IpAddrKind {
    V4,
    V6,
}

fn route(kind: IpAddrKind) {
    println!("routing {kind:?}");
}

fn main() {
    let four = IpAddrKind::V4;
    let six = IpAddrKind::V6;
    route(four);
    route(six);
}

#[derive(Debug)]
enum IpAddr {
    V4(u8, u8, u8, u8),
    V6(String),
}

fn main() {
    let home = IpAddr::V4(127, 0, 0, 1);
    let loopback = IpAddr::V6(String::from("::1"));
    println!("{home:?} {loopback:?}");
}

#[derive(Debug)]
enum Message {
    Quit,                       // no data
    Move { x: i32, y: i32 },    // named fields, like a struct
    Write(String),              // one String
    ChangeColor(i32, i32, i32), // three numbers
}

impl Message {
    fn call(&self) {
        println!("handling {self:?}");
    }
}

fn main() {
    let msgs = [Message::Write(String::from("hello")), Message::Move { x: 1, y: -2 }, Message::Quit];
    for m in &msgs {
        m.call();
    }
}

