enum Shape {
    Circle(f64),
}

impl Shape {
    fn describe(&self) -> String {
        match self {
            Shape::Circle(r) => format!("circle with radius {r}"),
        }
    }
}

fn main() {
    let shapes = [Shape::Circle(1.0)];
    for s in &shapes {
        println!("{}", s.describe());
    }
}
